// API client for backend communication
const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

// Generic API call function
export const apiCall = async (endpoint, method = 'GET', data = null) => {
  const options = {
    method,
    headers: {
      'Content-Type': 'application/json',
    },
  };

  if (data) {
    options.body = JSON.stringify(data);
  }

  try {
    const response = await fetch(`${API_URL}${endpoint}`, options);

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.error || `HTTP ${response.status}`);
    }

    return await response.json();
  } catch (error) {
    console.error('API Error:', error.message);
    throw error;
  }
};

// Auth endpoints
export const authAPI = {
  login: (email, password) =>
    apiCall('/auth/login', 'POST', { email, password }),

  signup: (name, email, password, role = 'student') =>
    apiCall('/auth/signup', 'POST', { name, email, password, role }),

  getAllUsers: () =>
    apiCall('/auth/users', 'GET'),
};

// Request endpoints
export const requestAPI = {
  getAllRequests: () =>
    apiCall('/requests', 'GET'),

  getUserRequests: (studentId) =>
    apiCall(`/requests/user/${studentId}`, 'GET'),

  createRequest: (studentId, studentName, category, title, description) =>
    apiCall('/requests', 'POST', {
      studentId,
      studentName,
      category,
      title,
      description,
    }),

  updateRequest: (id, status) =>
    apiCall(`/requests/${id}`, 'PUT', { status }),
};
